struct Node;

fn bound(mut s: String, max: usize) -> String {
    if s.len() > max {
        let mut cut = max;
        while cut > 0 && !s.is_char_boundary(cut) {
            cut -= 1;
        }
        s.truncate(cut);
    }
    s
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;
        let question = bound(q.question, 512);
        let knowledge = crate::aap::caps::kb_read::lookup(&question);
        ConversationContext {
            intent: q.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
